extern crate litex;
use litex::ast::{stmt::Stmt, fact::{Fact, AtomicFact}, obj::{Obj, ArithmeticOperator}};
use litex::execute::execute_fact_stmt::{VerifyState, VerifyStateLevel};
use litex::launch_command::{LaunchCommand, OutputLanguage};
use litex::runtime::Runtime;
use litex::tokenize::Tokenizer;
fn runtime() -> Runtime {
    Runtime::new(LaunchCommand::Eval { code: String::new(), session: false, strict: true, language: OutputLanguage::English })
}
fn main() {
    let goals = [
        ("product", "forall a,x,y R+:\n    a<1\n    =>:\n        log(a,x*y)=log(a,x)+log(a,y)\n"),
        ("quotient", "forall a,x,y R+:\n    a<1\n    =>:\n        log(a,x/y)=log(a,x)-log(a,y)\n"),
        ("reciprocal", "forall a,x R+:\n    a<1\n    =>:\n        log(a,1/x)=-log(a,x)\n"),
        ("argument_power", "forall a,x R+,n Z:\n    a<1\n    =>:\n        log(a,x^n)=n*log(a,x)\n"),
    ];
    for (goal,source) in goals {
        for (name,state) in [("builtin",VerifyState::new(VerifyStateLevel::BuiltinRule)),("strategy",VerifyState::new(VerifyStateLevel::Strategy)),("root",VerifyState::top_level())] {
            let mut rt=runtime();
            let tokens=Tokenizer::new().tokenize(source,rt.current_file.clone()).unwrap();
            let Stmt::Fact(fact)=rt.parse(&tokens).unwrap().remove(0) else {panic!("fact")};
            let wd=rt.verify_fact_well_definedness(&fact,state).unwrap();
            let proof=rt.verify_fact(&fact,state).unwrap();
            println!("{goal} {name}: wd_failed={}, proof_failed={}",wd.is_failed(),proof.is_failed());
        }
    }
    let reciprocal = "forall a,x R+:\n    a<1\n    =>:\n        log(a,1/x)=(-1)*log(a,x)\n";
    let mut rt=runtime();
    let tokens=Tokenizer::new().tokenize(reciprocal,rt.current_file.clone()).unwrap();
    let Stmt::Fact(Fact::ForallFact(fact))=rt.parse(&tokens).unwrap().remove(0) else {panic!("forall")};
    let then: Fact = fact.then_facts[0].clone().into();
    let Fact::AtomicFact(AtomicFact::EqualFact(fact))=&then else {panic!("equal")};
    let Obj::ArithmeticOperator(ArithmeticOperator::Mul(mul))=&fact.right else {panic!("mul")};
    println!("reciprocal_multiplier_is_native_neg={}",matches!(&*mul.left,Obj::ArithmeticOperator(ArithmeticOperator::Neg(_))));
    let run=rt.run_litex_code(reciprocal).unwrap();
    println!("reciprocal success={}",run.success);
}

