import hashlib, json, pathlib, subprocess, sys, time
root = pathlib.Path.cwd()
name, command = sys.argv[1], sys.argv[2:]
def manifest():
    paths = list((root / 'src').rglob('*.rs')) + list((root / 'tests/unit/execute/common_obj_relations').rglob('*.rs')) + [root / 'tests/unit/execute/log_algebra_base/tests.rs'] + [root / 'Cargo.toml', root / 'Cargo.lock']
    return {str(p.relative_to(root)): hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(paths)}
before = manifest(); start = time.time()
p = subprocess.run(command, capture_output=True, text=True)
after = manifest()
r = {'command': command, 'exit_code': p.returncode, 'elapsed_seconds': time.time()-start, 'source_before': before, 'source_after': after, 'source_stable': before==after, 'stdout': p.stdout, 'stderr': p.stderr, 'binary_sha256': hashlib.sha256((root/'target/release/litex').read_bytes()).hexdigest()}
(root/f'tmp/2026-10-05/common-obj-relations/{name}.json').write_text(json.dumps(r, indent=2)+'\n')
print(json.dumps({k:v for k,v in r.items() if k not in ['source_before','source_after','stdout','stderr']}), flush=True)
if p.returncode:
    print(p.stdout[-10000:])
    lines = p.stderr.splitlines()
    for i,line in enumerate(lines):
        if line.startswith('error'):
            print('\n'.join(lines[max(0,i):i+18]))
else:
    print(p.stdout[-2000:])
    print(p.stderr.splitlines()[-1:])

raise SystemExit(p.returncode)
